    GENDER_ID INT,
    EYE_COLOUR_ID INT,
    HAIR_COLOUR_ID INT,
    SKIN_COLOUR_ID INT,
    RACE_ID INT,
    PUBLISHER_ID INT,
    ALIGNMENT_ID INT,
